(window.NTDATA=window.NTDATA||{});(NTDATA.rbo=NTDATA.rbo||{}).josh={"1":{"1":"После того как Моисей, раб Господа, умер, Господь сказал его помощнику – Иисусу Навину:","2":"«Моисей, Мой раб, умер. Теперь переведи народ Израиля через Иордан – в страну, которую Я дарую этому народу.","3":"Я отдам вам все земли, куда ступит ваша нога, – так Я обещал Моисею.","4":"От Пустыни и от Ливанских гор, до Великой Реки – Евфрата (включая всю землю хеттов) и до Великого моря на западе – все это будет ваша страна.","5":"Никто не сможет тебе противостоять, до самого конца твоих дней. Я был с Моисеем – и точно так же Я буду с тобою: Я не оставлю тебя и не покину.","6":"Будь твердым и стойким! Ты сделаешь эту страну владением сынов Израилевых – Я отдаю им эту страну, как поклялся их отцам!","7":"Будь же твердым и стойким! Строго соблюдай и исполняй Закон, который тебе велел соблюдать Мой раб Моисей. Ни на шаг не отступай от этого Закона – и тебе повсюду будет сопутствовать успех.","8":"Пусть слова из свитка Закона непрестанно будут у тебя на устах. Повторяй их днем и ночью, строго соблюдай и исполняй все, что написано в этом свитке, – и тебе будут сопутствовать удача и успех.","9":"Я повелеваю тебе: будь твердым и стойким! Не робей и не бойся: с тобою везде будет Господь, твой Бог».","10":"Иисус велел старостам","11":"обойти весь стан и передать народу приказ: «Готовьте еду в дорогу. Через три дня вы перейдете Иордан, чтобы овладеть страной, которую вам дарует Господь, ваш Бог».","12":"А племени Рувима, племени Гада и половине племени Манассии Иисус сказал:","13":"«Помните, какой наказ вам дал Моисей, раб Господа? Господь, ваш Бог, отдал вам эти земли, даровал мирную жизнь.","14":"Пусть же теперь ваши жены, дети и скот остаются здесь, за Иорданом, на землях, которые вам дал Моисей, – а вы, воины, идите в боевом строю в первых рядах сынов Израилевых. Помогайте им,","15":"пока Господь не дарует им мирную жизнь, как даровал ее вам. А когда они овладеют той страной, которую им дарует Господь, ваш Бог, вы вернетесь в свои владения – в земли, которые вам дал Моисей, раб Господа, к востоку от Иордана».","16":"Они ответили Иисусу: «Мы выполним все, что ты повелишь. Мы пойдем туда, куда ты прикажешь.","17":"Мы будем повиноваться тебе, как повиновались Моисею, – только пусть Господь, твой Бог, будет с тобою, как Он был с Моисеем.","18":"Что бы ты ни повелел нам, – всякий, кто тебя ослушается и не подчинится твоему приказу, будет предан смерти. Только ты сам будь твердым и стойким!»"},"2":{"1":"Из Шиттима Иисус Навин тайно послал двоих на разведку. «Идите, – сказал он им, – и разузнайте про эту страну и про город Иерихон». Они отправились в Иерихон, пришли в дом публичной женщины по имени Раав и там заночевали.","2":"Царю Иерихона донесли: «Этой ночью сюда пришли несколько израильтян, чтобы разузнать про нашу страну».","3":"Царь послал к Раав своих людей с приказом: «Выдай нам тех, кто к тебе пришел. Это лазутчики, они пришли в нашу страну на разведку».","4":"Но Раав спрятала обоих лазутчиков, а людям царя ответила: «Да, какие-то мужчины побывали у меня. Я не знаю, откуда они.","5":"Когда стемнело и настало время закрывать городские ворота, они ушли. Куда они пошли, я не знаю. Но поспешите: может быть, вы их догоните!»","6":"На самом же деле она отвела лазутчиков на крышу и спрятала под сложенными там стеблями льна.","7":"Люди царя пустились в погоню по дороге, которая ведет к Иордану, и дошли до самого брода. После того как они вышли из города, ворота закрыли.","8":"Не успели лазутчики улечься спать, как Раав поднялась к ним на крышу","9":"и сказала: «Я знаю, что Господь отдал вам нашу страну. Мы все в страхе перед вами. Всех жителей страны охватил ужас!","10":"Мы слышали, что когда вы шли из Египта Господь превратил перед вами море Суф в сушу. Мы слышали, что вы сделали с двумя аморейскими царями Заиорданья, с Сихоном и Огом, – как вы уничтожили их, предав заклятью!","11":"Мы услышали это, и сердца наши замерли от страха; ни у кого нет смелости противостоять вам. Ведь Господь, ваш Бог, – это Бог, властвующий над небесами вверху и над землей внизу!","12":"Поклянитесь мне Господом, что как я вам сделала добро, так и вы отплатите моему роду добром. Дайте мне надежный знак,","13":"что вы сохраните жизнь моему отцу и матери, моим братьям, сестрам и всем их семьям – что вы избавите нас всех от смерти!»","14":"Лазутчики отвечали: «Мы ручаемся своей жизнью за ваши жизни! Если вы никому про нас не расскажете, то когда Господь отдаст нам эту землю, мы отплатим вам добром за добро».","15":"И тогда Раав помогла им спуститься из окна по веревке (ее дом был частью городской стены, так что стена служила ей жилищем).","16":"«Идите в горы, – сказала она им, – чтобы не встретиться с людьми, которые отправились вас искать. Прячьтесь там три дня, пока они не вернутся домой, а после идите своей дорогой».","17":"Лазутчики сказали Раав: «Вот как мы выполним клятву, которую дали тебе.","18":"Когда мы придем в эту страну, ты должна привязать вот этот алый шнурок к окну, через которое ты нам помогла спуститься. Собери у себя отца, мать, братьев и весь свой род.","19":"Если кто-то из них выйдет из твоего дома на улицу, он сам повинен в своей смерти – мы не виновны. Но если тронут того, кто будет у тебя дома, – вина на нас.","20":"А если ты хоть кому-нибудь расскажешь про нас, то мы больше не связаны этой клятвой».","21":"Она ответила: «Пусть будет, как вы сказали». Раав простилась с лазутчиками, они ушли, а она привязала к окну алый шнурок.","22":"Лазутчики направились в горы и прятались там три дня – пока их преследователи не вернулись домой, обыскав всю дорогу и никого не найдя.","23":"После этого оба лазутчика пошли обратно. Они спустились с гор, перешли реку и, представ перед Иисусом Навином, рассказали ему все, что с ними случилось.","24":"«Господь отдал нам всю эту страну, – сказали они Иисусу. – Ее жители охвачены ужасом перед нами»."},"3":{"1":"Рано утром Иисус со всеми сынами Израилевыми выступил из Шиттима к Иордану. Там, не переходя реку, они расположились на ночлег.","2":"Когда миновало три дня, старосты обошли весь стан","3":"и объявили народу такой приказ: «Как только вы увидите, что священники – левиты понесли ковчег договора с Господом, вашим Богом, – тут же ступайте за ними.","4":"(Но между вами и ковчегом должно быть расстояние в две тысячи локтей, ближе не подходите.) Так вы поймете, куда вам идти, – ведь раньше вы этим путем не ходили».","5":"Иисус велел народу: «Освятите и очистите себя, ибо завтра Господь совершит среди вас чудеса».","6":"Иисус велел священникам: «Возьмите ковчег договора и ступайте вперед, во главе народа». Они взяли ковчег договора и пошли вперед, во главе народа.","7":"И Господь сказал Иисусу: «Сегодня Я возвышу тебя в глазах израильтян. Они поймут, что Я – с тобою, как Я был с Моисеем.","8":"Прикажи священникам, несущим ковчег договора, чтобы они остановились, как только ступят в воды Иордана».","9":"Иисус велел израильтянам: «Подойдите сюда и слушайте слово Господа, вашего Бога».","10":"Он сказал: «Сейчас вы узнаете, что с вами Бог Живой, который отдаст вам эту землю, отобрав ее у ханаанеев, и хеттов, и хиввеев, и периззеев, и гиргашеев, и амореев, и евусеев!","11":"Смотрите, ковчег договора с Владыкой всей земли движется перед вами к Иордану.","12":"Вы должны отрядить из племен Израиля двенадцать человек, по одному человеку от каждого племени.","13":"Когда ноги священников, несущих ковчег Господа, Владыки всей земли, ступят в воды Иордана, вода в Иордане иссякнет. Все воды, что текут с верховьев, остановятся и встанут стеной».","14":"Народ снялся со стоянки и направился к Иордану. Впереди священники несли ковчег договора.","15":"Была пора жатвы; Иордан разлился, затопляя берега. Но как только священники, несущие ковчег, подошли к Иордану и их ноги ступили в воду,","16":"вода, что течет из верховьев Иордана, остановилась и встала стеной – вдали, близ Адама (это город рядом с Цартаном). Вода, что течет вниз, в Мертвое (Соленое) море, ушла, иссякла. И народ перешел реку, напротив Иерихона.","17":"Священники, несущие ковчег договора с Господом, твердо стояли на высохшем дне Иордана, а все израильтяне шли на другой берег посуху. Так было, пока весь народ не перешел Иордан."},"4":{"1":"Когда весь народ перешел через Иордан, Господь сказал Иисусу:","2":"«Отрядите двенадцать человек, по одному от каждого племени,","3":"и велите им взять отсюда, со дна Иордана, с того места, где стоят священники, двенадцать камней. Унесите эти камни с собою и поставьте там, где вы будете сегодня ночевать».","4":"Иисус призвал к себе двенадцать человек, которых он выбрал из племен Израиля (по одному человеку от каждого племени),","5":"и приказал им: «Ступайте на середину Иордана, к ковчегу Господа, вашего Бога, и пусть каждый из вас унесет оттуда на своих плечах по камню – столько камней, сколько племен у Израиля.","6":"Эти камни будут для вас памятным знаком. В будущем, когда ваши сыновья спросят: „Что означают для вас эти камни?\" –","7":"вы расскажете им, как остановились воды Иордана перед ковчегом договора с Господом. Понесли ковчег через Иордан – и воды остановились! Эти камни будут для Израиля вечным напоминанием».","8":"Израильтяне выполнили приказ Иисуса: взяли со дна Иордана двенадцать камней – по числу племен Израиля, как Господь велел Иисусу, – унесли эти камни с собой и поставили там, где заночевали.","9":"(Иисус воздвиг на дне Иордана двенадцать камней, на которых стояли священники, несшие ковчег договора). Эти камни и по сей день там.","10":"Священники, несшие ковчег, стояли на середине Иордана, пока не было исполнено все, что Господь через Иисуса повелел народу (все, что Моисей заповедал Иисусу). Народ быстро перешел на другой берег,","11":"а когда все перешли, священники с ковчегом Господа вновь двинулись вперед, во главе народа.","12":"Племена Рувима и Гада и половина племени Манассии шли в боевом строю в первых рядах сынов Израилевых – как велел им Моисей.","13":"Около сорока тысяч воинов шли пред Господом в Иерихонскую долину, готовые к бою.","14":"В тот день Господь возвеличил Иисуса в глазах израильтян. С тех пор они чтили Иисуса так же, как чтили Моисея, пока тот был жив.","15":"Господь сказал Иисусу:","16":"«Вели священникам, несущим ковчег Завета, подняться на берег».","17":"Иисус велел священникам: «Поднимайтесь на берег».","18":"Как только священники, несшие ковчег договора с Господом, поднялись на берег и их ноги ступили на сушу, воды Иордана вернулись и потекли как прежде, затопляя берега.","19":"В десятый день первого месяца израильтяне перешли Иордан и стали лагерем в Гилгале, к востоку от Иерихона.","20":"В Гилгале Иисус воздвиг двенадцать камней, взятых со дна Иордана.","21":"Он сказал израильтянам: «В будущем, когда сыновья спросят у вас: „Что означают эти камни?\" –","22":"вы расскажете им, как Израиль посуху перешел Иордан.","23":"Господь, ваш Бог, обратил эту реку в сушу, чтобы вы перешли ее, – так перед нами Он обратил в сушу море Суф, чтобы мы его перешли.","24":"Это свершилось, чтобы все народы земли знали, как сильна рука Господня, и чтобы вы сами всегда боялись и чтили Господа, вашего Бога!»"},"5":{"1":"Цари амореев, чьи земли лежали к западу от Иордана, и ханаанеев, чьи земли лежали у моря, узнали, что Господь остановил воды Иордана, чтобы израильтяне перешли его. Замерли от страха сердца этих царей – ни у кого не было смелости противостоять израильтянам.","2":"В то время Господь сказал Иисусу: «Сделай каменные ножи и вновь соверши обрезание израильского народа».","3":"Иисус сделал каменные ножи и совершил у холма Аралот обрезание израильтян.","4":"(Вот почему Иисусу пришлось совершить это обрезание. Все мужчины, которые покинули Египет во взрослом возрасте, воинами, умерли в скитаниях по пустыне.","5":"Они, вышедшие из Египта, были обрезаны – но тем, кто родился после, во время скитаний по пустыне, обрезание не делали.","6":"Израильтяне скитались по пустыне сорок лет, пока не умерли все, кто ушел из Египта во взрослом возрасте, воинами. Они ослушались Господа, и Господь поклялся: не увидят они той земли, источающей молоко и мед, которую Господь, говоря с нашими отцами, поклялся отдать нам.","7":"На смену умершим Господь взрастил их сыновей – и теперь Иисус сделал им обрезание. А до этого, поскольку в пути обрезание не делали, все они были необрезанными.)","8":"Когда весь народ был уже обрезан и, оставшись в стане, дожидался выздоровления,","9":"Господь сказал Иисусу: «Сегодня Я снял с вас египетский позор!» С тех пор это место так и зовется: Гилгал.","10":"Израильтяне стали лагерем в Гилгале и в четырнадцатый день месяца, вечером, справили Пасху на равнине близ Иерихона.","11":"На следующий день после Пасхи они ели пищу из плодов этой земли: пресные лепешки и жареное зерно.","12":"И с того дня, когда они стали есть пищу из плодов этой земли, со дня, следующего за Пасхой, манна уже не появлялась. С тех пор не было у израильтян манны, в тот год они питались урожаем ханаанской земли.","13":"Однажды, близ Иерихона, Иисус увидел перед собой человека с обнаженным мечом в руке. «Ты наш или ты враг?» – спросил Иисус, подойдя к нему.","14":"«Ни то ни другое, – отвечал тот. – Я вождь воинства Господнего, и поэтому я здесь». Иисус простерся перед ним, пав ниц, и спросил: «Что господин мой скажет мне, рабу своему?» –","15":"«Сними сандалии, – велел ему вождь воинства Господнего. – Место, на котором ты стоишь, свято». Иисус повиновался.","16":"Ворота Иерихона в то время были закрыты и заперты – жители боялись израильтян. Никто не выходил из города, никто не входил в него."},"6":{"1":"Господь сказал Иисусу: «Я отдаю в твои руки Иерихон, и его царя, и могучих воинов.","2":"Пусть все ваше войско шесть дней подряд обходит вокруг города – по одному разу в день.","3":"Перед ковчегом должны идти семь священников, каждый с рогом в руках. На седьмой день обойдите вокруг города семь раз, и пусть священники трубят в рог.","4":"А когда затрубит рог – когда вы услышите зов трубы – пусть все ваше войско издаст громкий боевой клич. Тогда стены Иерихона рухнут и вы войдете в город, сразу со всех сторон».","5":"Созвав священников, Иисус Навин сказал им: «Несите ковчег договора. И пусть семь священников, каждый с рогом в руках, идут перед ковчегом Господа».","6":"Войску Иисус приказал: «Ступайте, обойдите вокруг города. И пусть перед ковчегом Господа идут воины, готовые к бою».","7":"Когда Иисус отдал войску такой приказ, семь священников, каждый с рогом в руках, пошли, трубя, вперед, пред Господом; за ними следовал ковчег договора с Господом.","8":"Перед священниками, трубившими в рога, шли воины, готовые к бою, а за ковчегом – отряд, замыкающий шествие. Не умолкая трубили рога.","9":"Иисус приказал войску: «Не издавайте боевого клича. Пусть не слышно будет вашего голоса. Пусть ни слова не слетает с ваших уст. Настанет день, когда я прикажу вам издать боевой клич, – и вот тогда кричите!»","10":"Они обнесли ковчег Господа вокруг города один раз и возвратились в стан на ночлег.","11":"На другой день Иисус встал рано утром – и священники вновь понесли ковчег Господа.","12":"Семь священников, каждый с рогом в руках, шли, трубя, перед ковчегом Господа. Перед ними шли воины, готовые к бою, а за ковчегом Господа – отряд, замыкающий шествие. Не умолкая трубили рога.","13":"Так, на второй день, они еще раз обошли вокруг города и вернулись в стан. Они делали так в течение шести дней.","14":"На седьмой день они встали с зарею и обошли вокруг города, в обычном порядке, но семь раз. (Лишь в этот день они семь раз обходили город.)","15":"На седьмой раз, когда священники затрубили в рога, Иисус приказал войску: «Издайте боевой клич! Господь отдал вам этот город!","16":"Вместе со всеми, кто в нем находится, этот город предан заклятью: он должен быть уничтожен – отдан Господу. Лишь Раав, публичную женщину, оставьте в живых, вместе со всеми, кто будет у нее в доме, – за то что она спрятала наших разведчиков.","17":"Остерегайтесь того, что предано заклятью. Если вы что-то предадите заклятью, а потом возьмете заклятое, то заклятье падет на весь стан израильтян и вы наведете на него беду!","18":"А серебро, золото, медные и железные изделия – посвящены Господу, и их надо положить в сокровищницу Господа».","19":"И все войско прокричало боевой клич. Трубили рога. Громкий боевой клич издали израильтяне, когда услышали звук рога, – и стены города рухнули! Воины ворвались в город со всех сторон и овладели им.","20":"Они предали заклятью, все живое, что было в городе, – перебили мечом мужчин и женщин, детей, и стариков, быков, овец, коз, ослов.","21":"Двум лазутчикам, которые ходили в эту страну на разведку, Иисус сказал: «Исполните свою клятву: ступайте в дом той публичной женщины и выведите ее из города, вместе со всеми ее родными».","22":"Тогда эти юноши – лазутчики, пошли, вывели из города и Раав, и весь ее род – отца, мать, братьев, родных – и увели их подальше от стана израильтян.","23":"Город и все, что в нем было, израильтяне сожгли. Серебро, золото, медные и железные изделия положили в сокровищницу дома Господнего.","24":"А Раав, публичную женщину, и весь ее род – всех родных ее – Иисус оставил в живых, за то что она спрятала лазутчиков, которых Иисус послал в Иерихон на разведку. Ее род и по сей день живет среди израильтян.","25":"В ту пору Иисус произнес проклятие: «Проклят пред Господом тот, кто вновь отстроит город Иерихон. Заложит он основанье – потеряет старшего сына! Навесит ворота – потеряет младшего сына!»","26":"Господь был с Иисусом, и слух об Иисусе прошел по всей стране."},"7":{"1":"Но израильтяне нарушили заклятье. Ахан, сын Карми, сына Завди, сына Зераха, из племени Иуды, взял себе то, что было предано заклятью, – и разгорелся гнев Господень на сынов Израилевых.","2":"Из Иерихона Иисус послал своих людей в город Ай, что близ Бет – Авена (к востоку от Бет – Эля). «Ступайте, разузнайте про эту страну», – велел он им. Они сходили в Ай на разведку","3":"и, вернувшись, сказали Иисусу: «Всему войску туда идти не нужно. Пусть пойдут две – три тысячи – этого хватит, чтобы завоевать Ай. Людей там немного, не утомляй этим походом весь народ».","4":"Около трех тысяч человек отправились в поход – и обратились в бегство перед жителями Ая.","5":"Тридцать шесть человек убили жители Ая: они гнались за израильтянами по склону горы – от городских ворот до каменоломен – и убивали их. После этого сердца израильтян замерли от страха и стали как вода.","6":"Иисус разорвал свои одежды и простерся ниц пред ковчегом Господа и до вечера не вставал с земли, и вместе с ним – старейшины Израиля. Головы свои они посыпали пылью.","7":"«О Владыка, Господь, – говорил Иисус, – зачем Ты перевел этот народ через Иордан? Чтобы отдать нас в руки амореев и погубить нас? О, лучше бы мы остались за Иорданом!","8":"О Владыка мой! Что скажу я теперь, когда израильтяне обратились в бегство перед врагами?","9":"Узнают про это ханаанеи и все, кто живет в этой стране, – и окружат они нас, и сотрут наше имя с лица земли! Но если Ты допустишь такое – что будет с Твоим великим именем?»","10":"«Встань, – повелел Господь Иисусу. – Что ты лежишь здесь, простершись ниц?","11":"Израильтяне согрешили, нарушили договор, который Я им велел соблюдать. Они взяли то, что было предано заклятью, – украли, утаили, спрятали среди своих вещей!","12":"Теперь они не смогут противостоять врагам и будут обращаться перед ними в бегство! Теперь они сами попали под заклятье и обречены на уничтожение! Не буду Я больше с вами – пока вы не уничтожите у себя все, что предано заклятью.","13":"Освяти и очисти народ. Объяви им: „К завтрашнему дню вы должны освятиться и очиститься, ибо так говорит Господь, Бог Израиля: у вас, израильтяне, есть вещи, преданные заклятью! Пока вы не избавитесь от всего, что предано заклятью, вы не сможете противостоять врагам.","14":"Пусть наутро сюда подходит племя за племенем. Из того племени, на которое укажет Господь, пусть подходит один род за другим. Из того рода, на который укажет Господь, пусть подходит семья за семьей. Из семьи, на которую укажет Господь, пусть подходит один мужчина за другим.","15":"Кто будет уличен, что у него есть вещи, преданные заклятью, тот должен быть сожжен вместе со всеми его домашними: он нарушил договор с Господом, он запятнал Израиль гнусным делом!\"»","16":"На следующий день, рано утром, Иисус велел израильтянам подходить к нему, племя за племенем, – и было указано на племя Иуды.","17":"Он велел подходить родам Иудиным – и было указано на род Зераха. Велел подходить мужчинам из рода Зераха – и было указано на Завди.","18":"Велел подходить мужчинам из его семьи – и было указано на Ахана, сына Карми, сына Завди, сына Зераха, из племени Иуды.","19":"«Сын мой! – сказал Иисус Ахану. – Прославь Господа, Бога Израилева, воздай Ему хвалу! И расскажи мне, что ты сделал. Не скрывай от меня ничего».","20":"И Ахан сказал Иисусу: «Да, это я согрешил против Господа, Бога Израилева. Вот как это было.","21":"Я увидел среди добычи роскошную шинарскую мантию, серебро – двести шекелей – и слиток золота весом в пятьдесят шекелей. Мне очень захотелось взять это, и я взял. Все это зарыто у меня в шатре; серебро – в самом низу».","22":"Люди Иисуса побежали по его приказу в шатер Ахана – и нашли все это спрятанным у него в шатре; серебро было в самом низу.","23":"Они забрали все это из шатра, принесли к Иисусу и всему народу Израиля – и положили пред Господом.","24":"После этого Иисус и все израильтяне взяли Ахана, сына Зераха, – вместе с этим серебром, мантией и слитком золота, вместе с его сыновьями и дочерьми, быками и ослами, овцами и козами, вместе с его шатром, вместе со всем, что у него было, – и повели в долину Ахор.","25":"«Зачем ты навел на нас беду? – сказал ему Иисус. – Ныне Господь навел беду на тебя!» И все израильтяне насмерть забили Ахана камнями. Всех, кого они туда привели, израильтяне забили камнями и сожгли,","26":"а поверх набросали большую груду камней – она и по сей день там. После этого гнев Господа утих. А место это с тех пор и доныне зовется долиной Ахор."},"8":{"1":"Господь сказал Иисусу: «Не страшись, не бойся! Иди со всем войском в поход на Ай. Я отдаю в твои руки айского царя, его народ, город и всю его страну.","2":"Поступите с Аем и его царем так же, как с Иерихоном и его царем (но добычу и скот возьмите себе). Устрой засаду рядом с Аем, по ту сторону города».","3":"Иисус со всем войском выступил в поход на Ай. Отобрав тридцать тысяч лучших воинов, он ночью послал их вперед,","4":"с таким приказом: «Устройте засаду по ту сторону города, не слишком далеко от него, и будьте все наготове.","5":"А я со всем войском подойду к городу. Когда его жители, как и в прошлый раз, выйдут сразиться с нами, мы обратимся в бегство.","6":"Они погонятся за нами – и так мы уведем их от города: они подумают, что мы убегаем от них, как в прошлый раз. Мы побежим,","7":"а вы выходите из засады и вступайте в город. Господь, ваш Бог, отдаст его в ваши руки.","8":"Когда захватите город – сожгите его; сделайте, что вам велел Господь. Таков мой приказ вам».","9":"Иисус велел им выступать; они пошли и устроили засаду между Бет – Элем и Аем, к западу от Ая. Иисус остался ночевать с остальными,","10":"а рано утром, собрав все войско, вместе со старейшинами Израиля повел его на Ай.","11":"Воины во главе с Иисусом подошли к городу","12":"и встали лагерем к северу от него. От города их отделяла долина. Около пяти тысяч человек Иисус разместил в засаде, между Бет – Элем и Аем, к западу от города.","13":"(Войско располагалось так: основные силы – к северу от города, а один отряд – к западу.) Ночью Иисус спустился в долину.","14":"Царь Ая увидел это – и наутро воины Ая спешно выступили из города на бой с израильтянами. Вместе со всем своим войском царь двинулся (как и было задумано) в сторону Иорданской долины. Не знал он, что по другую сторону от города была засада.","15":"Иисус и все израильтяне притворились, что разбиты, и бросились бежать в пустыню.","16":"Всех жителей Ая позвали присоединиться к погоне – и, преследуя Иисуса, они далеко отошли от города.","17":"Ни одного мужчины не осталось ни в Ае, ни в Бет – Эле – все бросились преследовать израильтян. Оставили город открытым – и устремились в погоню за израильтянами.","18":"Тогда Господь сказал Иисусу: «Протяни свой меч в сторону Ая. Я отдаю этот город в твои руки!» Иисус протянул свой меч в сторону Ая –","19":"и тут же его воины вышли из засады. Они ворвались в город, овладели им и немедленно подожгли.","20":"Обернулись воины Ая и видят: горит их город, дым поднимается к небу! И деться им было некуда, потому что израильтяне, бежавшие по пустыне, тут же повернули назад и бросились на своих преследователей.","21":"Когда Иисус и израильтяне увидели, что сидевшие в засаде захватили город, что над городом поднимается дым, они тут же повернули назад и напали на воинов Ая.","22":"А другой отряд устремился на воинов Ая со стороны города. Так израильтяне окружили своих врагов и перебили их: никто не уцелел, никто не смог убежать!","23":"Лишь айского царя взяли живым и привели к Иисусу.","24":"После того как все войско Ая, гнавшееся за израильтянами, было уничтожено в пустыне – истреблено мечом до последнего человека – израильтяне вернулись в город и перебили мечом всех, кто там оставался.","25":"Всего в тот день были убиты двенадцать тысяч человек, и мужчины и женщины, – все, кто жил в Ае.","26":"Иисус не опускал простертого меча до тех пор, пока не истребил, предав заклятью, всех, кто жил в Ае.","27":"Скот и добычу из этого города израильтяне взяли себе – так велел Иисусу Господь.","28":"А город Иисус сжег – навеки превратил его в безлюдный холм. Таков Ай и по сей день.","29":"Айского царя Иисус повесил на столбе. Тело царя висело на столбе до вечера, а на закате Иисус велел снять его и бросить перед городскими воротами. Сверху накидали огромную груду камней. Она и по сей день там.","30":"В ту пору Иисус воздвиг на горе Гевал жертвенник Господу, Богу Израиля,","31":"как повелел сынам Израиля Моисей, раб Господа, и как написано в свитке Закона Моисея, – жертвенник из необработанных камней (камней, которых не касалось железное орудие). На этом жертвеннике израильтяне принесли Господу жертвы всесожжения и закололи пиршественные жертвы.","32":"Затем Иисус в присутствии всех сынов Израилевых переписал на камни Закон Моисея (Закон, который был написан Моисеем).","33":"Все израильтяне, вместе со своими старейшинами, старостами и судьями, стояли по сторонам ковчега, перед священниками – левитами, что носят ковчег договора с Господом. Вместе стояли и коренные израильтяне, и присоединившиеся к ним переселенцы: половина народа – со стороны горы Гаризим, половина – со стороны горы Гевал. (Именно так Моисей, раб Господа, некогда повелел благословлять народ Израиля.)","34":"После этого Иисус прочел вслух все, что было написано в Законе, – и благословения и проклятия, записанные в свитке Закона.","35":"Не пропустив ни единого слова, Иисус прочел всей общине Израиля – включая женщин, детей и переселенцев, которые присоединились к общине, – все, что заповедал Моисей."},"9":{"1":"О происшедших событиях узнали цари, чьи владения лежали к западу от Иордана – в горах, в предгорьях и вдоль побережья Великого Моря, вплоть до Ливанских гор, – цари хеттов, амореев, ханаанеев, периззеев, хиввеев и евусеев.","2":"И тогда они объединились, чтобы вместе воевать против Иисуса и Израиля.","3":"А жители Гаваона, узнав, что сделал Иисус с Иерихоном и Аем,","4":"решили пойти на хитрость. Они отправились в путь, взяв с собою еды в дорогу: навьючили на ослов потрепанные мешки и потрепанные, порванные и зашитые мехи с вином.","5":"Они надели потрепанные, чиненые – перечиненые сандалии и истрепанную одежду. Хлеб, который они взяли с собою, был сухой и крошился.","6":"Так они пришли к Иисусу, в его стан, в Гилгал. «Мы пришли из далекой страны, – сказали они Иисусу и израильтянам. – Заключите с нами договор о мире!» –","7":"«Как мы можем заключить с вами договор? – ответили этим хиввеям израильтяне. – А вдруг вы живете на нашей земле?!»","8":"Иисусу хиввеи сказали: «Мы рабы твои!» – «Кто вы и откуда?» – спросил он их.","9":"И они отвечали: «Мы, рабы твои, пришли из очень далекой страны. Мы пришли из-за славы Господа, твоего Бога. Мы знаем о Нем и знаем, что Он совершил в Египте","10":"и что Он сделал с двумя аморейскими царями Заиорданья – с Сихоном, царем Хешбона, и с Огом, царем Башана, правившим в Аштароте.","11":"И поэтому наши старейшины и все жители нашей страны дали нам такое поручение: „Возьмите еды в дорогу и ступайте к этому народу. Скажите им, что мы их рабы – пусть заключат с нами договор о мире\".","12":"Вот наш хлеб. У нас дома, когда мы, направляясь к вам, собирали еду в дорогу, он был еще теплый, а теперь засох и раскрошился.","13":"Вот мехи с вином. Когда мы их наполняли, они были новыми, а теперь совсем изорвались. Наша одежда и сандалии износились от долгой дороги».","14":"Израильтяне осмотрели их дорожные припасы, а Господа вопрошать не стали.","15":"Иисус заключил с хиввеями договор о мире – пообещал сохранить им жизнь – и вожди общины Израиля дали им клятву.","16":"А через три дня после заключения договора израильтяне узнали, что это их соседи, живущие здесь, на их земле.","17":"Израильтяне отправились в поход и подступили, на третий день, к хиввейским городам – Гаваону, Кефире, Беэроту и Кирьят – Неариму.","18":"Но они не стали нападать на эти города, ведь вожди общины поклялись Господом, Богом Израиля. Весь народ негодовал на то, что сделали вожди общины,","19":"но те сказали народу: «Мы поклялись Господом, Богом Израиля, и теперь не можем тронуть их.","20":"Оставим их жить, чтобы Гнев не обрушился на нас за нарушение клятвы!»","21":"Вожди общины постановили: «Пусть живут». И с тех пор хиввеи работают на общину: доставляют дрова и воду. Так решили начальники общины.","22":"Иисус позвал хиввеев и сказал им: «Зачем вы обманули нас, зачем говорили, что живете далеко от нас, если на самом деле вы живете рядом с нами?","23":"Прокляты вы за это: вы навеки будете в рабстве, будете доставлять дрова и воду для дома Бога моего».","24":"Они отвечали: «Нам, рабам твоим, известно, какое повеление Господь, ваш Бог, дал Своему рабу Моисею: что вся эта земля долж – на быть отдана вам, а все ее жители уничтожены. Мы боялись за свою жизнь – вот почему мы так поступили.","25":"Теперь мы в твоей власти – делай с нами, как считаешь нужным».","26":"Иисус не дал израильтянам убить хиввеев,","27":"но велел, чтобы хиввеи, начиная с того самого дня, доставляли дрова и воду для общины Израиля и для жертвенника Господнего (на то место, которое изберет Господь). Эти работы они выполняют и поныне."},"10":{"1":"Адони - Цедек, царь Иерусалима, узнал, что Иисус захватил Ай, уничтожил его, предав заклятью (как поступил Иисус с Иерихоном и его царем, так поступил он и с Аем и его царем). Узнал Адони – Цедек и о том, что жители Гаваона заключили с израильтянами договор о мире и будут жить в их владениях.","2":"Адони – Цедек и его люди испугались, ведь Гаваон был большим городом – не меньше, чем столица какого-нибудь царства (даже больше, чем Ай), а жители его были храбрыми воинами.","3":"И тогда Адони – Цедек, царь Иерусалима, послал гонцов к Хохаму, царю Хеврона, Пираму, царю Ярмута, Яфиа, царю Лахиша, Девиру, царю Эглона, и велел передать им:","4":"«Присоединяйтесь ко мне, помогите мне разгромить га_ ваонцев – за то что они заключили с Иисусом и израильтянами договор о мире».","5":"И вот, пять аморейских царей – цари Иерусалима, Хеврона, Ярмута, Лахиша и Эглона – собрали все свои войска и стали осаждать Гаваон.","6":"Жители Гаваона воззвали к Иисусу, который стоял лагерем в Гилгале: «Не оставляй нас, рабов твоих! Спеши к нам на помощь, спаси нас! Все аморейские цари, что правят в этих горах, объединились против нас».","7":"Иисус со всем войском, со всеми своими храбрыми воинами, выступил из Гилгала.","8":"«Не бойся врагов, – сказал ему Господь. – Я отдам их в твои руки. Никто из них не сможет противостоять тебе».","9":"Иисус появился перед врагами неожиданно – всю ночь он шел из Гилгала.","10":"При появлении израильтян Господь привел врагов в смятение. Израильтяне наголову разгромили их под Гаваоном, а затем преследовали по бет – хоронской дороге и дальше, вплоть до Азеки и Маккеды, убивая бегущих.","11":"Когда бегущие, спасаясь от израильтян, устремились по бет – хоронской дороге, Господь стал бросать на них огромные камни с неба – и беглецы гибли. Так было до самой Азеки. От камней, падавших градом, погибло еще больше людей, чем от меча израильтян.","12":"В тот день, когда Господь даровал Израилю победу над амореями, Иисус говорил с Господом – сказал на глазах у всего Израиля: «Солнце, остановись над Гаваоном, и ты, луна, – над долиною Айялона!»","13":"И остановилось солнце, и луна не двигалась с места – пока народ расправлялся с врагами. (Именно так сказано в Книге Достойного.) Солнце остановилось посреди неба, целый день не спешило зайти!","14":"Ни до этого, ни после не было такого дня – чтобы Господь послушался человека! Сам Господь воевал за израильтян!","15":"А затем Иисус и все израильтяне вернулись в свой стан, в Гилгал.","16":"Пять аморейских царей бежали и спрятались в пещере близ Маккеды.","17":"Когда Иисусу сказали, что этих царей нашли, что они прячутся в пещере близ Маккеды,","18":"он приказал: «Завалите вход в пещеру большими камнями и поставьте стражу,","19":"но сами не останавливайтесь. Преследуйте врагов, бейте их в спину, не давайте им укрыться в городах – Господь, ваш Бог, отдал врагов вам в руки!»","20":"А после того как Иисус и израильтяне наголову разгромили врагов, перебив их почти полностью (лишь немногим удалось укрыться в укрепленных городах),","21":"все войско вернулось в стан, в Маккеду, и собралось вокруг Иисуса. Все они были невредимы, ни один волос не упал с их головы!","22":"«Теперь откройте вход в пещеру, – приказал Иисус. – Приведите ко мне из пещеры этих пятерых царей!»","23":"Его приказ выполнили и привели к нему из пещеры пятерых царей – царя Иерусалима, царя Хеврона, царя Ярмута, царя Лахиша и царя Эглона.","24":"Когда этих царей привели, Иисус созвал всех израильтян и приказал вождям, которые ходили вместе с ним на битву: «Подойдите и наступите этим царям на шеи!» Те подошли и наступили им на шеи.","25":"Иисус сказал: «Ничего не бойтесь, не страшитесь, будьте твердыми и стойкими! Вот что сделает Господь со всеми вашими врагами, со всеми, против кого вы воюете!»","26":"Затем Иисус убил этих царей и повесил их трупы на пяти столбах. Они висели там до вечера.","27":"На закате Иисус велел снять трупы со столбов и бросить в пещеру, где эти цари прятались, а вход в пещеру завалить большими камнями. Эти камни и по сей день там.","28":"В тот же день Иисус захватил Маккеду. Он перебил ее жителей и убил царя – уничтожил, предав заклятью, город и всех, кто в нем жил, до последнего человека. С царем Маккеды Иисус поступил так же, как с царем Иерихона.","29":"От Маккеды Иисус, вместе со всеми израильтянами, двинулся к Ливне и напал на нее.","30":"И Ливну Господь отдал в руки израильтян вместе с ее царем. Иисус уничтожил город и всех, кто в нем жил, до последнего человека. С царем Ливны он поступил так же, как с царем Иерихона.","31":"От Ливны Иисус, вместе со всеми израильтянами, двинулся к Лахишу и осадил его.","32":"Господь отдал Лахиш в руки израильтян: уже на следующий день Иисус захватил город. Он уничтожил город и всех, кто в нем жил, – сделал с Лахишем то же, что и с Ливной.","33":"В это время Хорам, царь Гезера, шел на помощь Лахишу, но Иисус разбил его наголову – уничтожил все его войско, до последнего человека.","34":"От Лахиша Иисус, вместе со всеми израильтянами, двинулся к Эглону и осадил его.","35":"В тот же день они захватили город и уничтожили его. Иисус, предав заклятью, истребил всех, кто жил в городе, точно так же, как он сделал это с Лахишем.","36":"От Эглона Иисус, вместе со всеми израильтянами, поднялся к Хеврону и напал на него.","37":"Они захватили город и уничтожили его, и царя, и окрестные селения, и всех, кто жил в городе, до последнего человека. Иисус сделал с Хевроном то же, что и с Эглоном: уничтожил, предав заклятью, город и всех, кто жил в нем.","38":"Затем Иисус, вместе со всеми израильтянами, повернул к Девиру и напал на него.","39":"Захватив город, вместе с его царем, а также окрестные селения, они перебили всех жителей – уничтожили, предав заклятью, всех, кто жил в городе, до последнего человека. Как поступил Иисус с Хевроном, как поступил он с Ливной и ее царем – так же он поступил с Девиром и его царем.","40":"Иисус истребил всех жителей этой страны – всех, кто жил в горах, в Негеве, в Шефеле и на склонах, – вместе со всеми их царями. Он уничтожил, предав заклятью (так повелел Господь, Бог Израиля), всех, кто жил в этой стране, до последнего человека, –","41":"от Кадеш – Барнеа до Газы, и по всей области Гошен, и до самых границ Гаваона.","42":"Одним ударом разгромил Иисус всех местных царей и захватил их земли, потому что Сам Господь, Бог Израиля, сражался за израильтян.","43":"После этого Иисус и все израильтяне вернулись в свой стан, в Гилгал."},"11":{"1":"Когда Явин, царь Хацора, узнал об этих событиях, он послал гонцов к Иовиву, царю Мадона, к царям Шимрона и Ахшафа,","2":"к царям, что правили на севере – в горах, и в Иорданской долине, к югу от озера Киннерет, и в предгорьях, и на западе – в Нафот – Доре.","3":"Он созвал ханаанеев с востока и запада, а также амореев, хеттов, периззеев и евусеев, что жили в горах, и хиввеев, что жили у подножья Хермона, в земле Мицпа .","4":"Все эти цари выступили в поход, со своими воинами, многочисленными, как песок морской, с огромным множеством коней и колесниц.","5":"Соединив свои войска, они стали лагерем у Меромского ключа, готовые сразиться с израильтянами.","6":"Но Господь сказал Иисусу: «Не бойся их. Я обещаю, что завтра, к этому часу, все они будут убиты израильтянами. Ты перережешь жилы их лошадям и сожжешь их колесницы».","7":"Иисус со своим войском внезапно подступил к Меромскому ключу и напал на врагов.","8":"Господь отдал их в руки израильтян. Израильтяне разбили их и преследовали вплоть до Великого Сидона, до Мисрефот – Маима, и до самой долины Мицпе на востоке. Они перебили их всех до последнего человека.","9":"Иисус поступил с врагами так, как велел ему Господь, – перерезал жилы лошадям и сжег колесницы.","10":"Повернув назад, Иисус захватил Хацор и убил его царя (а до того времени Хацор был главным среди окрестных царств).","11":"Всех, кто жил в городе, израильтяне перебили мечом – уничтожили, предав заклятью. Никого в живых не осталось. Иисус сжег Хацор.","12":"Захватив этих царей и их города, Иисус всех истребил – уничтожил, предав заклятью, как велел ему Моисей, раб Господа.","13":"(Но города, стоявшие на холмах, израильтяне не сожгли – один лишь Хацор был сожжен Иисусом.)","14":"Добычу и скот из захваченных городов израильтяне брали себе, но людей истребляли мечом всех до единого, никого не оставляя в живых.","15":"Так Господь повелел Моисею, Своему рабу, так Моисей повелел Иисусу – так Иисус и сделал, не отклоняясь от повелений, которые Господь дал Моисею.","16":"Иисус завоевал всю страну: горы, весь Негев, всю область Гошен, Шефелу, долину Иордана, а также горы и предгорья Израиля –","17":"все земли от горы Халак, что в предгорьях Сеира, до Баал – Гада, что в Ливанской долине, у подножья Хермона. Всех царей этой страны Иисус захватил и предал смерти.","18":"Но война с ними была долгой.","19":"Ни один город – никто, кроме хиввеев, живших в Гаваоне, – не заключил с израильтянами договора о мире. Все города израильтяне брали с боем.","20":"Господь побудил эти народы решиться на войну с израильтянами – для того, чтобы израильтяне уничтожили их, предав заклятью, чтобы не было этим народам пощады, чтобы все они были истреблены, как повелел Господь Моисею.","21":"В ту пору Иисус совершил поход против анакимов и истребил их всех, по всему нагорью – в Хевроне, Девире и Анаве, по всем горам Иудеи и Израиля. Всех анакимов, вместе с их городами, он уничтожил, предав заклятью.","22":"В земле израильтян не осталось ни одного анакима (они уцелели только в Газе, Гате и Ашдоде).","23":"Завоевав всю эту страну, как и обещал Господь Моисею, Иисус отдал ее во владение израильтянам – поделил между племенами. В стране воцарился покой, война окончилась."},"12":{"1":"Вот цари, которых израильтяне разбили – и завладели их землями, что простирались на восток от Иордана: от Арнонской долины до горы Хермон (включая восточную половину Иорданской долины).","2":"Сихон, аморейский царь. Его столицей был Хешбон. Ему принадлежали земли начиная от Ароэра, что над Арнонской долиной, и сама Арнонская долина, половина Галаада (вплоть до реки Яббок, за которой живут аммонитяне),","3":"а также Иорданская долина – от восточного берега озера Киннерет до восточного берега Мертвого (Соленого) моря, до Бет – Иешимота и склонов горы Фасга на юге.","4":"Ог, царь Башана, из последних рефаимов. Его столицами были Аштарот и Эдреи.","5":"Ему принадлежали гора Хермон, Салха, весь Башан – до границы с гешурцами и маахейцами, а также половина Галаада (до границ Сихона, царя хешбонского).","6":"Моисей, раб Господа, и израильтяне победили этих царей. Моисей, раб Господа, отдал их земли во владение племенам Рувима и Гада и половине племени Манассии.","7":"Вот цари, которых израильтяне во главе с Иисусом победили на землях, лежащих к западу от Иордана – между Баал – Гадом, что в Ливанской долине, и горой Халак, что в предгорьях Сеира. (Все эти земли Иисус отдал во владение племенам Израиля: разделил между ними","8":"и горы, и Шефелу, и долину Иордана, и склоны, и пустыню, и Негев.) Вот эти цари – хетты, амореи, ханаанеи, периззеи, хиввеи и евусеи.","9":"Царь Иерихона – один, царь Ая, что близ Бет – Эля, – один,","10":"царь Иерусалима – один, царь Хеврона – один,","11":"царь Ярмута – один, царь Лахиша – один,","12":"царь Эглона – один, царь Гезера – один,","13":"царь Девира – один, царь Гедера – один,","14":"царь Хормы – один, царь Арада – один,","15":"царь Ливны – один, царь Адуллима – один,","16":"царь Маккеды – один, царь Бет – Эля – один,","17":"царь Таппуаха – один, царь Хефера – один,","18":"царь Афека – один, царь Сарона – один,","19":"царь Мадона – один, царь Хацора – один,","20":"царь Шимрона – один, царь Ахшафа – один,","21":"царь Таанаха – один, царь Мегиддо – один,","22":"царь Кедеша – один, царь Иокнеама, что на Кармиле, – один,","23":"царь Дора, что в Нафат – Доре, – один, царь Гоима, что в Галилее, – один,","24":"царь Тирцы – один. Всего – тридцать один царь."},"13":{"1":"Иисус был уже глубоким стариком. Господь сказал ему: «Ты уже совсем стар, а земель, которыми надо овладеть, еще очень много.","2":"Это все филистимские области и вся страна гешурцев.","3":"(Все земли от Шихора, что у египетской границы, и до северной границы Экрона считаются частью Ханаана; там пять филистимских княжеств – Газа, Ашдод, Ашкелон, Гат и Экрон.) Это земля аввеев,","4":"на юге. Это все ханаанские земли от Ары, что принадлежит сидонянам, до Афека и аморейских пределов.","5":"Это область Библа, а на востоке – весь Ливан от Баал – Гада, что у подножья Хермона, до Лево - Хамата.","6":"Я отберу землю у всех, кто живет в этих горах, от Ливана до Мисрефот – Маима, – у всех сидонян – и отдам ее сынам Израилевым! Раздели землю по жребию между израильтянами, как Я тебе повелел.","7":"Раздели всю страну между девятью племенами и половиной племени Манассии».","8":"Половине племени Манассии (а вместе с ней – племенам Рувима и Гада) уже были даны наделы – Моисей дал им землю к востоку от Иордана. Моисей, раб Господа, отдал им","9":"земли начиная от Ароэра, что над Арнонской долиной, и селение, что в Арнонской долине, а также все Плоскогорье от Медевы до Дивона","10":"и все города правившего в Хешбоне аморейского царя Сихона (вплоть до страны аммонитян),","11":"а также Галаад и страну гешурцев и маахейцев, всю гору Хермон и весь Башан, вплоть до Салхи","12":"(все земли Ога, царя башанского, что правил в Аштароте и Эдреи; он был из последних рефаимов). Моисей победил этих царей и завладел их землями.","13":"(Но израильтяне не завладели землей гешурцев и маахейцев – те живут среди сынов Израилевых и по сей день.)","14":"А племени Левия Моисей не дал никакого надела. Их доля – так сказал им Моисей – это приношения Господу, Богу Израиля.","15":"Моисей дал земли племени Рувима – всем его родам.","16":"Это земли начиная от Ароэра, что над Арнонской долиной, и селение, что в Арнонской долине, а также все Плоскогорье, вплоть до Медевы,","17":"Хешбон и все селения, что рядом с ним на Плоскогорье, – Дивон, Бамот – Баал, Бет – Баал – Меон,","18":"Яхац, Кедемот, Мефаат,","19":"Кирьятаим, Сивма, Церет – Шахар, что на холме посреди долины,","20":"Бет – Пеор, склоны горы Фасга и Бет – Иешимот –","21":"все селения Плоскогорья, все царство Сихона, аморейского царя, который правил в Хешбоне. (Моисей победил и его самого, и подвластных ему мидьянских вождей Эви , Рекема, Цура, Хура и Реву, живших в этой стране.","22":"Вместе с прочими израильтяне убили и прорицателя Валаама, сына Беора.)","23":"Граница владений племени Рувима – Иордан. Это селения и хутора, вошедшие в надел родов Рувима.","24":"Моисей дал земли племени Гада – всем его родам.","25":"Это Язер, все селения Галаада и половина страны аммонитян (до Ароэра, что близ Раввы ) –","26":"земли от Хешбона до Рамат – Мицпе и Бетонима, от Маханаима до области Ло – Девара;","27":"и в долине – Бет – Харам, Бет – Нимра, Суккот и Цафон. (То есть вся оставшаяся часть царства Сихона, царя хешбонского, – Заиорданье вплоть до озера Киннерет.)","28":"Это селения и хутора, вошедшие в надел родов Гада.","29":"Моисей дал земли половине племени Манассии (родам половины племени Манассии).","30":"Это земли начиная от Маханаима, весь Башан (все царство Ога, царя башанского), все Яировы Деревни в Башане (шестьдесят селений),","31":"половина Галаада, а также Аштарот и Эдреи – башанские города, в которых правил Ог. Все это было отдано потомкам Махира, сына Манассии (половине родов Махира).","32":"Такой раздел земли совершил Моисей на Моавской равнине, к востоку от Иордана – Иерихонской реки.","33":"А племени Левия он не дал никакого надела. Их доля – так сказал им Моисей – это Господь, Бог Израиля."},"14":{"1":"Вот наделы, которые были даны сынам Израилевым в Ханаане. Священник Элеазар, Иисус Навин и главы родов израильских племен распределили эти наделы","2":"по жребию между девятью с половиной племенами Израиля, как повелел Господь через Моисея.","3":"Двум с половиной племенам Моисей уже дал наделы в Заиорданье. Левитам он надела не дал.","4":"Потомки Иосифа образовали два племени – Манассии и Ефрема. (Левитам земель не дали – лишь города для жительства и вокруг этих городов пастбища для скота.)","5":"Сыны Израилевы сделали так, как Господь повелел Моисею: разделили землю между собой.","6":"В Гилгале к Иисусу подошли сыны Иуды – и Калев, сын Иефунне, кениззей, сказал Иисусу: «Ты помнишь, что говорил Господь про нас с тобой Моисею, человеку Божьему, в Кадеш – Барнеа?","7":"Сорок лет мне было, когда Моисей, раб Господа, послал меня из Кадеш – Барнеа в эту страну на разведку. Вернувшись, я правдиво рассказал ему обо всем.","8":"Другие израильтяне, ходившие со мной на разведку, испугали людей своими рассказами – но я был верен Господу, моему Богу.","9":"И тогда Моисей дал мне такую клятву: „Земля, по которой ступала твоя нога, будет вовек принадлежать тебе и твоим потомкам – за то что ты верен Господу, моему Богу\".","10":"И вот, Господь, как и обещал, дал мне дожить до нынешнего дня. Сорок пять лет минуло с тех пор, как Он обещал это Моисею, – тогда израильтяне шли через пустыню. Сейчас мне восемьдесят пять лет,","11":"но я так же крепок, как и в тот день, когда Моисей послал меня на разведку. Я все так же силен, готов к боям и походам.","12":"Отдай мне нагорье, о котором говорил тогда Господь! Ты сам слышал в тот день, что там – анакимы, что там – большие и укрепленные города. Но если Господь будет со мною, я завладею этой землей – так обещал Господь!»","13":"Иисус благословил Калева, сына Иефунне, и дал ему во владение Хеврон.","14":"Хеврон и по сей день остается наделом Калева, сына Иефунне, кениззея, – ибо Калев был верен Господу, Богу Израиля.","15":"А раньше Хеврон назывался Кирьят – Арба (Арба был главным среди анакимов). В стране воцарился покой, война окончилась."},"15":{"1":"Племени Иуды – всем его родам – достался по жребию надел, который на самом юге примыкает к землям Эдома и к пустыне Цин.","2":"Южная граница этого надела начинается у края Мертвого моря (у южной оконечности моря),","3":"затем проходит к югу от Скорпионова подъема, минует Цин и идет вверх, южнее Кадеш – Барнеа. Далее граница минует Хецрон, поднимается к Аддару, поворачивает к Карке ,","4":"минует Ацмон, идет по Египетской ложбине и достигает моря. Это ваша южная граница.","5":"Восточная граница – это Мертвое море, до самого устья Иордана. Северная граница начинается от оконечности Мертвого моря (от устья Иордана),","6":"поднимается к Бет – Хогле, проходит севернее Бет – Аравы, идет вверх, к скале Бохана, сына Рувима,","7":"затем от долины Ахор поднимается к Девиру, поворачивает на север, к Гилгалу, что близ Адуммимского подъема (проходящего к югу от ущелья), оттуда идет к источнику Эн – Шемеш и достигает источника Рогель.","8":"Далее граница идет вверх по долине Бен – Хинном, южнее Евуса (то есть Иерусалима), поднимается к вершине той горы, что западнее долины Хинном и севернее долины Рефаимов,","9":"затем поворачивает к источнику Ме – Нефтоах, подходит к селениям горы Эфрон и поворачивает к Баале (то есть Кирьят – Иеариму).","10":"От Баалы граница сворачивает на запад, к горе Сеир, проходит севернее горы Иеарим (то есть Кесалон), спускается к Бет – Шемешу, минует Тимну ,","11":"проходит севернее Экрона, сворачивает к Шиккерону, минует гору Баала, выходит к Явнеэлу и достигает моря.","12":"Западная граница – это Великое море. Это границы земель, принадлежащих родам Иуды.","13":"Калеву, сыну Иефунне, был выделен надел на землях потомков Иуды – так повелел Иисусу Господь. Это Кирьят – Арба (то есть Хеврон), город Арбы, отца Анака.","14":"Калев отобрал этот город у трех анакимов – Шешая, Ахимана и Талмая, потомков Анака.","15":"Затем Калев пошел войной на жителей Девира. (Раньше Девир назывался Кирьят – Сефер.)","16":"Калев сказал: «Кто победит и захватит Кирьят – Сефер, тому я отдам в жены мою дочь Ахсу».","17":"Город захватил Отниэл, потомок Кеназа, брат Калева, и Калев отдал ему в жены свою дочь Ахсу.","18":"Пришла Ахса – и уговорила Отниэла просить у ее отца участок земли. «Что ты хочешь?» – спросил Калев у Ахсы, когда она соскочила с осла.","19":"«Дай мне свое благословение, – сказала Ахса. – Ты дал мне землю в Негеве, дай же и источники!» И Калев отдал ей источники – и верхние, и нижние.","20":"Вот надел родов племени Иуды.","21":"У границы с Эдомом, в Негеве, племени Иуды принадлежат селения: Кавцеэл, Арад, Ягур,","22":"Кина, Димона, Адада ,","23":"Кедеш, Хацор, Итнан,","24":"3иф, Телем, Беалот,","25":"Хацор – Хадатта, Керийот – Хецрон (то есть Хацор),","26":"Амам, Шема , Молада ,","27":"Хацар – Гадда, Хешмон, Бет – Пелет,","28":"Хацар – Шуал, Беэр – Шева и селения вокруг нее,","29":"Баала, Ийим, Эцем,","30":"Элтолад, Кесил, Хорма ,","31":"Циклаг, Мадманна, Сансанна ,","32":"Леваот, Шилхим, Аин и Риммон (всего – двадцать девять селений и хутора вокруг них).","33":"В Шефеле: Эштаол, Цора, Ашна ,","34":"3аноах, Эн – Ганним, Таппуах, Энам,","35":"Ярмут, Адуллам, Сохо, Азека ,","36":"Шаараим, Адитаим, Гедера и Гедеротаим (всего – четырнадцать селений и хутора вокруг них);","37":"Ценан, Хадаша, Мигдал – Гад,","38":"Дилад, Мицпе, Иоктеэл,","39":"Лахиш, Боцкат, Эглон,","40":"Каббон, Лахмас, Китлиш,","41":"Гедерот, Бет – Дагон, Наама и Маккеда (всего – шестнадцать селений и хутора вокруг них);","42":"Ливна , Этер, Ашан,","43":"Ифтах, Ашна , Нецив,","44":"Кеила, Ахзив и Мареша (всего – девять селений и хутора вокруг них);","45":"Экрон, селения и хутора вокруг него;","46":"селения, лежащие на запад от Экрона, рядом с Ашдодом, и хутора вокруг них;","47":"Ашдод, селения и хутора вокруг него; Газа, а также селения и хутора вокруг нее – вплоть до Египетской ложбины и Великого моря.","48":"В горах: Шамир, Яттир, Сохо ,","49":"Данна, Кирьят – Санна (то есть Девир),","50":"Анав, Эштемоа, Аним,","51":"Гошен, Холон и Гило (всего – одиннадцать селений и хутора вокруг них);","52":"Арав, Рума, Эшан,","53":"Янум, Бет – Таппуах, Афека,","54":"Хумта, Кирьят – Арба (то есть Хеврон) и Циор (всего – девять селений и хутора вокруг них);","55":"Маон, Кармил, Зиф, Ютта ,","56":"Изреель, Иокдеам, Заноах,","57":"Каин, Гива и Тимна (всего – десять селений и хутора вокруг них);","58":"Халхул, Бет – Цур, Гедор,","59":"Маарат, Бет – Анот и Элтекон (всего – шесть селений и хутора вокруг них); [Текоа, Эфрата (то есть Вифлеем), Пеор, Этам, Кулон, Татам, Шореш, Керем, Галлим, Бет – Эр и Манахат (всего – одиннадцать селений и хутора вокруг них)]","60":"Кирьят – Баал (то есть Кирьят – Иеарим) и Равва (всего – два селения и хутора вокруг них).","61":"В пустыне: Бет – Арава, Миддин, Сехаха ,","62":"Нившан, Ир – Мелах и Эн – Геди (всего – шесть селений и хутора вокруг них).","63":"Потомки Иуды не смогли отобрать Иерусалим у евусеев. Евусеи живут в Иерусалиме, вместе с потомками Иуды, и по сей день."},"16":{"1":"Потомкам Иосифа по жребию достался надел, который начинается у Иордана – Иерихонской реки (восточнее Иерихонского источника). От Иерихона граница идет по пустыне в горы, к Бет – Элю,","2":"от Бет – Эля – к Лузу, далее направляет – ся к области аркеев, к Атароту,","3":"затем идет на запад, спускаясь к области яфлетеев, к области Нижнего Бет – Хорона, к Гезеру – и достигает моря.","4":"Были выделены наделы потомкам Иосифа – племенам Манассии и Ефрема.","5":"Вот границы надела, который достался потомкам Ефрема (родам племени Ефрема). От Атрот – Аддара на востоке граница идет к Верхнему Бет – Хорону –","6":"и достигает моря. Северная граница – Михметат. На востоке граница поворачивает к Таанат – Шило, проходит дальше на восток, к Янохе,","7":"от Янохи спускается к Атароту и Нааре, подходит к Иерихону – и достигает Иордана.","8":"От Таппуаха граница идет на запад по руслу Каны – и достигает моря. Это надел родов племени Ефрема –","9":"селения, с хуторами вокруг них, выделенные из надела Манассии потомкам Ефрема.","10":"Племя Ефрема не отобрало Гезер у ханаанеев. Ханаанеи живут в наделе Ефрема и по сей день, но несут трудовую повинность."},"17":{"1":"Племени Манассии (Манассия – первенец Иосифа), потомкам Махира (Махир – первенец Манассии и отец Галаада, настоящий воин), тоже достался надел по жребию. Потомкам Махира достались земли Галаад и Башан.","2":"Достались наделы и прочим родам племени Манассии – родам Авиэзера, Хелека, Асриэла, Шехема, Хефера и Шемиды. Это шестеро мужчин – потомков Манассии, сына Иосифа, и произошедшие от них роды.","3":"Но у Целофхада, сына Хефера, сына Галаада, сына Махира, сына Манассии, не было сыновей – только дочери. Их имена – Махла, Ноа, Хогла, Милька и Тирца .","4":"Они пришли к священнику Элеазару, Иисусу Навину и вождям общины и сказали: «Господь повелел Моисею дать нам земли во владение, наравне с мужчинами из нашего племени». И, согласно повелению Господа, они тоже получили земли во владение, наравне с мужчинами из племени их отца.","5":"Так племени Манассии досталось десять областей, не считая Галаада и Башана, что лежат за Иорданом.","6":"(Те женщины из племени Манассии получили земли наравне с мужчинами, а кроме того, потомкам Манассии достался Галаад.)","7":"Земля Манассии простирается от Ашера до Михметата, что напротив Шехема. Оттуда граница идет на юг, к Эн – Таппуаху","8":"(область Таппуаха принадлежит Манассии, но сам Таппуах, лежащий на границе владений Манассии, принадлежит потомкам Ефрема).","9":"Далее граница идет вниз по руслу Каны (на юг от русла – те из селений Манассии, что были выделены Ефрему, а на север от русла – владения Манассии); граница достигает моря.","10":"Что к югу от русла, то принадлежит Ефрему, что к северу – Манассии; далее граница Манассии – море. На севере они граничат с Асиром, на востоке – с Иссахаром.","11":"На рубежах Иссахара и Асира Манассии отданы Бет – Шеан, Ивлеам, Дор, Эн – Дор, Тааних и Мегиддо, вместе с селениями вокруг них (третий из этих городов лежит в Нафат – Доре).","12":"Но потомки Манассии не смогли овладеть этими городами, и ханаанеи остались жить на этой земле.","13":"(Позже, когда израильтяне стали сильнее, они заставили ханаанеев нести трудовую повинность, но землями их так и не завладели.)","14":"Потомки Иосифа сказали Иисусу: «Почему ты дал нам во владение только один надел, одну область? Нас много, ведь нас поистине благословил Господь!»","15":"Иисус ответил: «Если вас много, то идите в леса и расчищайте для себя место – там, в земле периззеев и рефаимов, раз вам недостаточно гор Ефрема».","16":"Потомки Иосифа сказали: «Нам мало этих гор. А у ханаанеев, что живут в долинах (в Бет – Шеане и окрестных селениях, в Изреельской долине) – у них железные колесницы!»","17":"Иисус ответил потомкам Иосифа – племенам Ефрема и Манассии: «Вас много. Вы сильны. Не один только этот надел будет у вас,","18":"вам будут принадлежать все эти горы! Пусть они покрыты лесом – вы его расчистите, и горы будут вашими, от края до края. Вы завладеете землей ханаанеев, хоть и есть у них железные колесницы, хоть и сильны ханаанеи!»"},"18":{"1":"Вся община Израиля собралась в Силом. Там поставили шатер встречи. Вся страна уже была покорена,","2":"но семь племен Израиля еще не получили наделов.","3":"Иисус сказал израильтянам: «Долго еще вы будете медлить? Почему вы не вступаете во владение той землей, которую вам дал Господь, Бог ваших отцов?","4":"Отрядите от каждого племени по три человека, и я пошлю их обойти всю эту страну. Пусть составят ее описание – так, чтобы ее можно было разделить на наделы, – и вернутся ко мне.","5":"Они должны разделить страну на семь частей. За потомками Иуды сохраняются их земли на юге, за потомками Иосифа – их земли на севере,","6":"а вы опишете оставшуюся землю, поделив ее на семь частей. Это описание вы принесете мне, и здесь, пред лицом Господа, нашего Бога, я брошу о вас жребий.","7":"У левитов не будет надела на вашей земле, ибо их доля – жреческое служение Господу. А племена Гада, Рувима и половина племени Манассии уже получили от Моисея, раба Господа, наделы к востоку от Иордана».","8":"Посланные отправились в путь. Иисус велел им описать эту страну. «Идите, – сказал он им, – обойдите эту страну, опишите ее и возвращайтесь ко мне. А потом я брошу о вас жребий – здесь, в Силоме, пред лицом Господа».","9":"Они обошли страну и занесли в свиток все ее селения, поделив страну на семь частей. Затем они вернулись в Силом, в стан Иисуса.","10":"Там, в Силоме, пред лицом Господа, Иисус бросил жребий и разделил страну между племенами Израиля.","11":"Племени Вениамина – всем его родам – по жребию достался надел, который лежит между владениями потомков Иуды и Иосифа.","12":"Северная граница этого надела начинается от Иордана, огибает Иерихон с севера и идет на запад, в горы, к пустыне Бет – Авена.","13":"Далее граница идет к Лузу, огибает Луз (то есть Бет – Эль) с юга, идет к Атрот – Аддару и к той горе, что находится южнее Нижнего Бет – Хорона.","14":"Там граница поворачивает на юг, очерчивая западный край надела: от горы, что находится южнее Бет – Хорона, она идет к Кирьят – Баалу (то есть Кирьят – Иеариму) – городу, что принадлежит потомкам Иуды. Это – западная граница.","15":"Южная граница начинается от Кирьят – Иеарима. Она идет на запад, достигает источника Ме – Нефтоах,","16":"спускается к подножью горы, что рядом с долиной Бен – Хинном и севернее долины Рефаимов, идет вниз по долине Хинном, южнее Иевуса, и спускается к источнику Рогель.","17":"Затем граница поворачивает на север, к Эн – Шемешу, идет к Гелилоту, что близ Адуммимского подъема, и спускается к скале Бохана, сына Рувима.","18":"Далее граница проходит севернее Бет – Аравы, спускается в Иорданскую долину,","19":"идет севернее Бет – Хоглы и выходит к северной оконечности Мертвого моря (к устью Иордана). Это – южная граница.","20":"Восточная граница – Иордан. Это границы надела родов Вениамина.","21":"Племени Вениамина – всем его родам – принадлежат следующие селения: Иерихон, Бет – Хогла , Эмек – Кециц,","22":"Бет – Арава, Цемараим, Бет – Эль,","23":"Аввим, Пара, Офра ,","24":"Кефар – Аммони, Офни и Гева (всего – двенадцать селений и хутора вокруг них);","25":"Гаваон, Рама, Беэрот,","26":"Мицпе, Кефира, Моца ,","27":"Рекем, Ирпеэл, Тарала ,","28":"Цела - Элеф, Иевус (то есть Иерусалим), Гива и Кирьят – Иеарим (всего – четырнадцать селений и хутора вокруг них). Это надел родов Вениамина."},"19":{"1":"Второй жребий выпал Симеону – всем родам племени Симеона. Их надел – внутри надела потомков Иуды.","2":"В него входят селения: Беэр – Шева, Шема, Молада ,","3":"Хацар – Шуал, Бала , Эцем,","4":"Элтолад, Бетул, Хорма ,","5":"Циклаг, Бет – Маркавот, Хацар – Суса ,","6":"Бет – Леваот и Шарухен (всего – тринадцать селений и хутоpa вокруг них);","7":"Аин, Риммон, Этер и Ашан (всего – четыре селения и хутора вокруг них,","8":"а также все хутора, что находятся неподалеку от этих селений, вплоть до Баалат – Беэра и Рамат – Негева). Это надел родов племени Симеона.","9":"Он находится внутри области племени Иуды. Потомкам Иуды досталось больше земель, чем им было нужно, и поэтому из их земель был выделен надел для потомков Симеона.","10":"Третий жребий выпал потомкам Завулона – всем их родам. Их владения простираются до Сарида.","11":"От Сарида граница идет на запад, к Марале, и достигает Даббешета и той долины, что лежит напротив Иокнеама.","12":"В другую сторону – на восток – граница идет от Сарида, минуя область Кислот – Тавора, к Даверату, а потом поднимается к Яфиа.","13":"Оттуда граница идет дальше на восток, к Гат – Хеферу и Эт – Кацину, достигает Риммона – и поворачивает к Неа .","14":"Граница огибает Ханнатон с севера и достигает долины Ифтах – Эла.","15":"В надел входят Каттат, Нахалал, Шимрон, Идала и Вифлеем. Всего – двенадцать селений и хутора вокруг них.","16":"Это надел родов Завулона (селения и хутора вокруг них).","17":"Четвертый жребий выпал Иссахару – всем родам потомков Иссахара.","18":"В их надел входят Изреель, Кесуллот, Шунем,","19":"Хафараим, Шион, Анахарат,","20":"Раббит, Кишион, Эвец,","21":"Ремет, Эн – Ганним, Эн – Хадда, Бет – Паццец.","22":"Граница надела проходит по Фавору, Шахациму и Бет – Шемешу и достигает Иордана. Всего – шестнадцать селений и хутора вокруг них.","23":"Это надел родов племени Иссахара (селения и хутора вокруг них).","24":"Пятый жребий выпал племени Асира – всем его родам.","25":"В их надел входят Хелкат, Хали, Бетен, Ахшаф,","26":"Аламмелех, Амад и Мишал. На западе граница их земель доходит до Кармила и Шихор – Ливната.","27":"В другую сторону – на восток – граница идет к Бет – Дагону и подходит к землям Завулона и долине Ифтах – Эла (с севера). В надел входят Бет – Эмек и Неиэл. Далее граница идет к Кавулу – на север.","28":"В надел входят Авдон, Рехов, Хаммон и Кана. Достигнув Великого Сидона,","29":"граница поворачивает к Раме и доходит до Тирской крепости – поворачивает к Хосе и выходит к морю. В надел входят Махалев, Ахзив,","30":"Акко , Афек и Рехов. Всего – двадцать два селения и хутора вокруг них.","31":"Это надел родов племени Асира (селения и хутора вокруг них).","32":"Потомкам Неффалима – всем родам потомков Неффалима – выпал шестой жребий.","33":"Граница их надела идет от Хелефа и Цаананнимского дуба через Адами - Некев и Явнеэл, доходит до Лаккума – и достигает Иордана.","34":"В другую сторону – на запад – граница идет к Азнот – Тавору, а оттуда – к Хукоку. На юге их надел граничит с Завулоном, на западе – с Асиром, а с востока ограничен Иорданом.","35":"В надел входят крепости Циддим, Цер, Хаммат, Раккат, Киннерет,","36":"Адама, Рама, Хацор,","37":"Кедеш, Эдреи, Эн – Хацор,","38":"Ирон, Мигдал – Эл, Хорем, Бет – Анат и Бет – Шемеш. Всего – девятнадцать селений и хутора вокруг них.","39":"Это надел родов племени Неффалима (селения и хутора вокруг них).","40":"Седьмой жребий выпал племени Дана – всем его родам.","41":"В надел входят Цора , Эштаол, Ир – Шемеш,","42":"Шаалвим, Айялон, Итла ,","43":"Элон, Тимна; Экрон,","44":"Элтеке , Гиббетон, Баалат,","45":"Иехуд, Бене - Берак, Гат – Риммон,","46":"Ме – Яркон и Раккон, а также земли напротив Яффы.","47":"Но потомки Дана потеряли свой надел. Тогда они пошли, напали на Лешем, захватили его и перебили мечом всех его жителей. Этот город стал их владением: они поселились в нем и переименовали Лешем в Дан, по имени Дана, своего прародителя.","48":"Это надел родов племени Дана (селения и хутора вокруг них).","49":"Поделив между собой всю страну, израильтяне выделили на своих землях надел Иисусу Навину.","50":"Согласно велению Господа, они отдали Иисусу селение, которое Иисус для себя выбрал, – Тимнат – Серах, что в горах Ефрема. Иисус отстроил это селение и стал жить там.","51":"Таковы наделы, которые священник Элеазар, Иисус Навин и главы родов израильских племен распределили по жребию в Силоме, пред Господом, у входа в шатер встречи. На этом раздел земли завершился."},"20":{"1":"И Господь сказал Иисусу:","2":"«Вели сынам Израилевым выделить города для убежища, как Я повелел вам через Моисея, –","3":"чтобы всякий, кто случайно, без умысла, убьет человека, мог бежать туда и найти там убежище от кровной мести.","4":"Пусть он бежит в один из этих городов, встанет перед городскими воротами и расскажет старейшинам города, что произошло. Его должны впустить в город и дать ему место для жилья.","5":"Его не должны выдавать мстителю, когда тот придет за ним, – ведь убийство было неумышленным, а прежде между ним и убитым не было вражды.","6":"Пусть убийца живет в этом городе, пока не предстанет на суд общины (или пока не умрет верховный священник, при котором все это произошло, – тогда убийца может вернуться домой, в тот город, откуда бежал)».","7":"Городами – убежищами были провозглашены: Кедеш – в Галилее, в горах Неффалима; Шехем – в горах Ефрема; Кирьят – Арба (то есть Хеврон) – в горах Иудеи.","8":"А также города на восток от Иордана – Иерихонской реки: Бецер – в пустыне, на Плоскогорье (земля Рувима); Рамот – в Галааде (земля Гада); Голан – в Башане (земля Манассии).","9":"Постановили, что всякий, кто совершит неумышленное убийство, – будь то израильтянин или переселенец, живущий среди израильтян, – может укрываться в этих городах от кровной мести, пока не предстанет на суд общины."},"21":{"1":"Главы левитских родов пришли к священнику Элеазару, Иисусу Навину и главам родов израильских племен –","2":"это было в Силоме, в Ханаане, – и напомнили: «Господь повелел через Моисея, чтобы нам выделили селения, где мы будем жить, и пастбища вокруг них – для нашего скота».","3":"И тогда, согласно повелению Господа, израильтяне выделили для левитов из своих наделов селения и пастбища вокруг них.","4":"Сначала выпал жребий левитов из рода Кехата. Потомки священника Аарона получили по жребию тринадцать селений от племен Иуды, Симеона и Вениамина,","5":"а остальные левиты из рода Кехата – десять селений от племен Ефрема, Дана и от половины племени Манассии.","6":"Левиты из рода Гершона получили по жребию тринадцать селений от племен Иссахара, Асира, Неффалима и от той половины племени Манассии, что живет в Башане.","7":"Левиты из рода Мерари (все их семейства) получили двенадцать селений от племен Рувима, Гада и Завулона.","8":"Эти селения с пастбищами вокруг них израильтяне выделили для левитов по жребию, как повелел Господь через Моисея.","9":"Ниже перечислены селения, выделенные левитам из наделов Иуды и Симеона;","10":"эти селения были отданы потомкам Аарона, левитам из рода Кехата, потому что их жребий выпал первым.","11":"Кирьят – Арбу (то есть Хеврон), город Арбы, отца Анака, расположенный в горах Иудеи, отдали левитам, вместе с пастбищами вокруг него, –","12":"однако поля и деревни вокруг города отданы во владение Калеву, сыну Иефунне.","13":"Потомки священника Аарона получили Хеврон (город – убежище), с пастбищами вокруг него, а также Ливну ,","14":"Яттир, Эштемоа,","15":"Холон, Девир,","16":"Аин, Ютту и Бет – Шемеш, с пастбищами вокруг них. Всего – девять селений, из наделов двух племен.","17":"Кроме того, из надела Вениамина им были выделены Гаваон, Гева,","18":"Анатот и Алмон, с пастбищами вокруг них. Всего – четыре селения.","19":"В общей сложности потомки Аарона, священники, получили тринадцать селений вместе с пастбищами вокруг них.","20":"Остальные семейства левитов из рода Кехата получили по жребию следующие селения. Из надела Ефрема","21":"они получили: Шехем (городубежище), что в горах Ефрема, с пастбищами вокруг него, а также Гезер,","22":"Кивцаим и Бет – Хорон, с пастбищами вокруг них. Всего – четыре селения.","23":"Из надела Дана: Элтеке, Гиббетон,","24":"Айялон и Гат – Риммон, с пастбищами вокруг них. Всего – четыре селения.","25":"Из надела половины племени Манассии: Таанах и Гат – Риммон, с пастбищами вокруг них. Всего – два селения.","26":"В общей сложности остальные семейства из рода Кехата получили десять селений вместе с пастбищами вокруг них.","27":"Семейства левитов из рода Гершона получили следующие селения. Из надела половины племени Манассии: Голан (город – убежище), что в Башане, с пастбищами вокруг него, а также Аштарот, с пастбищами вокруг него. Всего – два селения.","28":"Из надела Иссахара: Кишион, Даверат,","29":"Ярмут и Эн – Ганним, с пастбищами вокруг них. Всего – четыре селения.","30":"Из надела Асира: Мишал, Авдон,","31":"Хелкат и Рехов, с пастбищами вокруг них. Всего – четыре селения.","32":"Из надела Неффалима: Кедеш (город – убежище), что в Галилее, с пастбищами вокруг него, а также Хаммот – Дор и Картан, с пастбищами вокруг них. Всего – три селения.","33":"В общей сложности семейства из рода Гершона получили тринадцать селений вместе с пастбищами вокруг них.","34":"Остальные левиты – семейства из рода Мерари – получили следующие селения. Из надела Завулона: Иокнеам, Карту ,","35":"Димну и Нахалал, с пастбищами вокруг них. Всего – четыре селения.","36":"Из надела Рувима: Бецер (город – убежище), Яхац,","37":"Кедемот и Мефаат, с пастбищами вокруг них. Всего – четыре селения.","38":"Из надела Гада: Рамот (город – убежище), что в Галааде, с пастбищами вокруг него, а также Маханаим,","39":"Хешбон и Язер, с пастбищами вокруг них. Всего – четыре селения.","40":"В общей сложности остальные семейства левитов – семейства из рода Мерари – получили по жребию двенадцать селений.","41":"В общей сложности левиты получили во владениях израильтян сорок восемь селений вместе с пастбищами вокруг них.","42":"(Вместе с каждым из этих селений они получали и окрестные пастбища.)","43":"Господь отдал израильтянам всю эту страну – как Он и обещал их отцам. Эта страна стала владением израильтян. Они поселились в ней,","44":"и Господь даровал им мирную жизнь – как Он и обещал их отцам. Никто не мог противостоять израильтянам – Господь отдал в их руки всех врагов.","45":"Ни одно из тех обещаний, что Господь дал израильтянам, не осталось неисполненным – все сбылось!"},"22":{"1":"Затем Иисус призвал племена Рувима, Гада и половину племени Манассии","2":"и сказал им: «Вы исполнили все, что повелел вам Моисей, раб Господа. Вы слушались всех моих повелений.","3":"Долго, вплоть до нынешнего дня, вы были вместе с остальными израильтянами, исполняя веление Господа, вашего Бога.","4":"Теперь, когда Господь, ваш Бог, выполнил Свое обещание и даровал им мирную жизнь, вы можете вернуться домой, в свои владения за Иорданом, которые вам дал Моисей, раб Господа.","5":"Но вы должны строго соблюдать и исполнять Закон – выполнять все, что повелел вам Моисей, раб Господа. Вы должны любить Господа, вашего Бога, следовать Его предначертаниям, исполнять Его повеления, хранить Ему верность и всю жизнь служить Ему всем сердцем, всей душой».","6":"Иисус благословил их и отпустил, они отправились домой.","7":"(Одной половине племени Манассии Моисей дал землю в Башане, а другой половине этого племени Иисус дал землю к западу от Иордана, рядом с остальными израильтянами.) Отпуская их домой и благословляя, Иисус","8":"сказал: «Вы возвращаетесь домой богатыми: теперь у вас много скота, много серебра, золота, меди, железа и одежд. Разделите с братьями добычу!»","9":"Расставшись с остальными израильтянами и покинув Силом, что в Ханаане, племена Рувима, Гада и половина племени Манассии отправились домой, в Галаад, в свой надел, которым они владели согласно повелению, данному Господом через Моисея.","10":"Придя к Гелилоту, что у Иордана, в Ханаане, племена Рувима, Гада и половина племени Манассии построили там, у Иордана, огромный жертвенник.","11":"Слух об этом дошел до остальных израильтян: они узнали, что племена Рувима, Гада и половина племени Манассии построили жертвенник на границе Ханаана – в Гелилоте, что у Иордана, на израильском берегу.","12":"И тогда вся община Израиля собралась в Силоме, чтобы идти на них войной.","13":"Сперва израильтяне послали в Галаад – к племенам Рувима, Гада и половине племени Манассии – священника Пинехаса, сына Элеазара.","14":"Вместе с ним отправились десятеро из вождей общины, из разных родов, – каждый представлял одно из племен Израиля. Каждый был предводителем одного из родов племени, представлял один из кланов Израиля.","15":"Прибыв в Галаад, к племенам Рувима, Гада и половине племени Манассии, послы сказали:","16":"«Так говорит вся община Господня: почему вы изменили Богу Израиля? Зачем отступаете вы от Господа? Построив свой жертвенник, вы восстали против Господа.","17":"Неужели мало нам преступлений пеорских? Мы доныне еще не очистились от этих грехов, за которые всю общину Господню постигла кара.","18":"Вы отступили от Господа! Сегодня вы восстали против Господа, а завтра Его гнев обрушится на всю общину Израиля!","19":"Если страна, которой вы владеете, осквернена, то переходите сюда, во владения Господа, где стоит скиния Господня, и возьмите себе землю здесь, у нас. Но не поднимайте восстание против Господа – и нас соучастниками не делайте – не стройте себе другого жертвенника, вдобавок к жертвеннику Господа, Бога нашего!","20":"Ведь когда Ахан, сын Зераха, согрешил и нарушил заклятие, то гнев Божий обрушился на всю общину Израиля! Многие, не он один, погибли из-за его греха».","21":"Племена Рувима, Гада и половина племени Манассии отвечали главам кланов Израиля:","22":"«Господь, Бог богов! Господь, Бог богов! Он знает, в чем дело, и пусть израильтяне тоже знают. Если мы согрешили, восстали против Господа – пусть не защищает Он нас отныне!","23":"Если мы построили этот жертвенник, чтобы, отступив от Господа, совершать на нем всесожжения, возносить приношения и пиршественные жертвы, – да покарает нас Господь!","24":"Но нет, мы построили его по другой причине. Мы боимся, что в будущем ваши потомки скажут нашим потомкам: „Что вам до Господа, Бога израильтян,","25":"о племена Рувима и Гада?! Господь сделал Иордан границей между нами и вами. Господь – не ваш Бог!\" И тогда, по вине ваших потомков, наши потомки перестанут чтить Господа!","26":"Вот мы и решили построить этот жертвенник – но вовсе не для всесожжении и пиршественных жертв.","27":"Пусть он будет для нас с вами – и для наших потомков – свидетельством того, что мы тоже можем служить Господу: совершать всесожжения и возносить пиршественные жертвы. Теперь уж ваши потомки не смогут сказать нашим потомкам: „Господь – не ваш Бог!\"","28":"Мы решили – если в будущем нам или нашим потомкам так скажут, то надо будет дать такой ответ: „Взгляните на это подобие жертвенника Господнего, которое воздвигли наши отцы. Оно – не для всесожжении и жертвоприношений. Оно – свидетельство для нас с вами\".","29":"Но не бывать тому, чтобы мы восстали против Господа и, отступив от Него, построили – вдобавок к тому жертвеннику Господа, Бога нашего, что стоит перед скинией, – еще один жертвенник для всесожжении, приношений и пиршественных жертв!»","30":"Священник Пинехас и сопровождавшие его вожди общины – главы кланов Израиля – обрадовались, услышав от племен Рувима, Гада и Манассии такой ответ.","31":"Священник Пинехас, сын Элеазара, сказал племенам Рувима, Гада и Манассии: «Теперь мы знаем, что Господь нас не покинул! Раз вы не изменили Господу, то Господь не станет карать Израиль».","32":"Расставшись с племенами Рувима и Гада и покинув Галаад, священник Пинехас, сын Элеазара, и вожди общины возвратились в Ханаан к израильтянам и рассказали им, в чем дело.","33":"Израильтяне обрадовались. Они благословили Бога и не стали воевать с племенами Рувима и Гада, не стали разорять их страну.","34":"Племена Рувима и Гада дали этому жертвеннику имя. Они сказали: «И для нас и для вас этот жертвенник будет свидетелем, что наш Бог – Господь»."},"23":{"1":"Много времени прошло с тех пор, как Господь даровал Израилю мирную жизнь; враги, окружавшие Израиль, больше не тревожили его. Иисус был уже глубоким стариком.","2":"Он созвал всех израильтян – старейшин, начальников общины, судей, старост – и сказал им: «Я уже глубокий старик.","3":"Вы видели, что сделал ради вас Господь, ваш Бог, – что сделал Он со всеми этими народами. Господь, ваш Бог, Сам воевал за вас!","4":"И вот, я разделил по жребию между вашими племенами землю всех народов, еще остающихся здесь, от Иордана до Великого моря на западе (равно как и землю всех народов, мною истребленных).","5":"Господь, ваш Бог, сметет эти народы перед вами – Он отберет у них землю и отдаст ее вам, и вы завладеете этой землей. Так обещал вам Господь, ваш Бог!","6":"Но вы должны строго соблюдать и исполнять все, что написано в свитке Закона Моисея, не отступая от этого Закона ни на шаг.","7":"Не смешивайтесь с народами, которые еще остаются в этой стране. Не призывайте их богов и не клянитесь именами их богов, не служите и не поклоняйтесь этим богам.","8":"Будьте верны Господу, вашему Богу, как это было до сих пор.","9":"Господь отобрал землю у больших и сильных народов и отдал ее вам. По сей день никто не может вам противостоять!","10":"Каждый из вас обращает в бегство тысячу, потому что Господь, ваш Бог, воюет за вас, как Он и обещал вам.","11":"Но смотрите же, всегда любите Господа, вашего Бога!","12":"А если вы отступитесь и присоединитесь к тем народам, которые еще остаются в этой стране, если будете вступать с ними в родство и смешиваться с ними, а они будут смешиваться с вами –","13":"то знайте: тогда и Господь, ваш Бог, уже не будет отбирать у этих народов землю и отдавать ее вам! Эти народы станут для вас ловушкой, западней, бичом для ваших ребер и колючкой для ваших глаз – и в конце концов вы сгинете с этой прекрасной земли, которую Господь, ваш Бог, даровал вам!","14":"Скоро мне идти в путь, который ждет каждого. Вы хорошо знаете: ни одно из тех обещаний, что Господь, ваш Бог, дал вам, не осталось неисполненным. Все они сбылись, ни одно неисполненным не осталось!","15":"Но как сбылись все обещания, которые вам дал Господь, ваш Бог, так исполнит Господь и все Свои угрозы – и в конце концов изгонит вас с этой прекрасной земли, которую Господь, ваш Бог, даровал вам.","16":"Если вы нарушите договор с Господом, вашим Богом, нарушите Его повеления, станете служить и поклоняться другим богам – тогда падет на вас гнев Господа и вы очень скоро сгинете из этой прекрасной страны, которую Он даровал вам»."},"24":{"1":"Иисус собрал в Шехем все племена Израиля, созвал старейшин и начальников общины, судей и старост. Все вместе предстали они пред Богом,","2":"и Иисус обратился к народу: «Так говорит Господь, Бог Израиля: „Издревле все ваши предки – вплоть до Тераха, который был отцом Авраама и Нахора, – жили за Рекой и служили чужим богам.","3":"Но Я увел оттуда вашего отца Авраама; Я вел его – и он обошел всю страну Ханаан. Я сделал его потомство многочисленным. Я даровал ему сына Исаака,","4":"а Исааку – сыновей Иакова и Исава. Исаву Я дал во владение Сеирские горы, а Иаков и его дети ушли в Египет.","5":"Мною были посланы Моисей и Аарон; Я покарал Египет, обрушив на него бедствия, и вызволил вас оттуда.","6":"Из Египта Я привел ваших предков к морю Суф, но там их настигли египетские колесницы и конница.","7":"Вы воззвали к Господу – и тогда Господь разделил вас и египтян тьмою. Господь обратил море против египтян, и море потопило их! Вы своими глазами видели, что сделал Я с египтянами! После этого вы долго жили в пустыне.","8":"Затем Я привел вас в страну амореев, в Заиорданье. Амореи напали на вас, но Я отдал их в ваши руки. Я истребил их, и вы завладели их землями.","9":"Балак, сын Циппора, царь Моава, начал войну с Израилем и призвал Валаама, сына Беора, чтобы он проклял вас.","10":"Но Я не желал слушать проклятия Валаама – и он благословил вас! Я спас вас от него!","11":"Вы перешли Иордан и подступили к Иерихону. С вами воевали горожане Иерихона, амореи, периззеи, ханаанеи, хетты, гиргашеи, хиввеи и евусеи, но Я отдал их всех в ваши руки.","12":"Не ваши мечи, не луки ваши, а осиный рой, который Я послал перед вами, убрал с вашего пути двух царей аморейских.","13":"Я даровал вам землю, которую вы не возделывали, и города, которых вы не строили, – и теперь вы живете в этих городах и вкушаете плоды олив и виноградников, посаженных не вами\"».","14":"«А потому, – сказал Иисус, – бойтесь и чтите Господа, служите Ему верой и правдой. Отвергните всех богов, которым служили ваши предки за Рекою и в Египте, и служите только Господу.","15":"Если же вы не хотите служить Господу, то выбирайте прямо сейчас, кому вы будете служить. Богам, которым служили ваши предки за Рекою? Или богам амореев, на чьей земле вы живете сейчас? Но я и весь мой род – мы будем служить Господу».","16":"И народ ответил: «Не бывать тому, чтобы мы оставили Господа и стали служить другим богам!","17":"Господь, Бог наш, вывел наш народ, наших предков, из египетской неволи. Он совершил у нас на глазах великие чудеса. Он хранил нас в дороге, Он защищал нас от народов, по землям которых мы шли.","18":"Он прогнал прочь от нас все эти народы – и амореев, живших в этой стране. Мы тоже будем служить Господу. Он – Бог наш!»","19":"Иисус сказал народу: «Не сможете вы служить Господу. Он – Бог Святой. Он – Бог ревнивый. Не станет Он терпеть ваше отступничество и грехи.","20":"Если вы оставите Господа и будете служить чужим богам, Он воздаст вам за это – после всех Своих благодеяний Он уничтожит вас!» –","21":"«Нет, мы будем служить Господу!» – ответил народ Иисусу.","22":"«Вы сами свидетели, что вы сделали выбор, решили служить Господу», – сказал Иисус. «Мы свидетели», – подтвердил народ.","23":"«Тогда отвергните всех чужих богов, какие у вас есть, – сказал Иисус, – и обратите все ваши помыслы к Господу, Богу Израиля!» –","24":"«Мы будем служить Господу, нашему Богу, будем Его слушаться», – ответил народ Иисусу.","25":"В тот день Иисус, от лица всего народа, заключил договор. Там, в Шехеме, он дал народу законы и правила –","26":"и записал их в свитке Божьего Закона. Он взял большой камень, поставил его под дубом, что в святилище Господа,","27":"и сказал народу: «Этот камень будет у нас свидетелем: он слышал все, что сказал нам Господь. Он будет свидетельствовать против вас, если вы отречетесь от вашего Бога».","28":"Иисус отпустил народ, и все разошлись по своим наделам.","29":"После этого Иисус Навин, раб Господа, умер. Ему было сто десять лет.","30":"Иисуса похоронили в его владениях, в Тимнат – Серахе, что в горах Ефрема, к северу от горы Гааш.","31":"Во времена Иисуса – и во времена переживших его старейшин, которые знали, какие дела совершил Господь для Израиля, – Израиль верно служил Господу.","32":"Останки Иосифа, унесенные из Египта, израильтяне погребли в Шехеме, на том самом участке земли, который был куплен Иаковом у сыновей Хамора, Шехемова отца, за сто кесит и стал владением потомков Иосифа.","33":"Умер Элеазар, сын Аарона. Его похоронили в наделе его сына Пинехаса – в Гиве Пинехасовой, что в горах Ефрема."}};
